 			* TICKS_PER_SECOND;
 	private static final int TICK_DURATION = 1000
 			* GameSpeed.NORMAL.getDeltaTimeMultiplied() / TICKS_PER_SECOND;
@@ -167,7 +164,11 @@ public abstract class GameSession {

 		if (!holdVote) {
